//! Base normalisation of restore: `restoreElementWithProperties`
//! (`packages/excalidraw/data/restore.ts:430-515` at the pinned commit
//! 438d89861f53d8a90ad566113ecac1b83761098f; research page
//! `site/content/research/data-model.md`, section 3.4).
//!
//! These are the rules as a readable table. The exhaustive check against
//! upstream's own output is `restore::tests::upstream_fixture` inside the
//! crate, which runs every case of `fixtures/restore-base.json`
//! (generated by `tools/goldens/restore-fixtures.mjs`).

use excali_core::restore::{
    normalize_link, normalized_dimensions, restore_element_with_properties, sanitize_url,
    RestoreEnv, RestoreError, TestEnv,
};
use serde_json::{json, Map, Value};

fn obj(v: Value) -> Map<String, Value> {
    match v {
        Value::Object(m) => m,
        _ => panic!("not an object"),
    }
}

fn restore(element: Value) -> Map<String, Value> {
    restore_with(element, &[])
}

fn restore_with(element: Value, extra: &[(&str, Option<Value>)]) -> Map<String, Value> {
    restore_element_with_properties(&obj(element), extra, &mut TestEnv::default())
        .expect("restores")
}

fn keys(m: &Map<String, Value>) -> Vec<&str> {
    m.keys().map(String::as_str).collect()
}

/// The defaults of `restoreElementWithProperties` (`restore.ts:449-493`) for
/// an element that only has a `type`: in upstream's test mode `randomId()`
/// is `id0` and `getUpdatedTimestamp()` is 1 (`random.ts:16`,
/// `utils.ts:552`), which `TestEnv` mirrors.
#[test]
fn defaults_for_a_bare_element() {
    let r = restore(json!({ "type": "rectangle" }));
    assert_eq!(
        Value::Object(r.clone()),
        json!({
            "type": "rectangle",
            "version": 1,
            "versionNonce": 0,
            "index": null,
            "isDeleted": false,
            "id": "id0",
            "fillStyle": "solid",
            "strokeWidth": 2,
            "strokeStyle": "solid",
            "roughness": 1,
            "opacity": 100,
            "angle": 0,
            "x": 0,
            "y": 0,
            "strokeColor": "#1e1e1e",
            "backgroundColor": "transparent",
            "width": 0,
            "height": 0,
            "seed": 1,
            "groupIds": [],
            "frameId": null,
            "roundness": null,
            "boundElements": [],
            "updated": 1,
            "created": null,
            "link": null,
            "locked": false
        })
    );
    // Missing keys are appended in the order of upstream's `base` literal.
    assert_eq!(
        keys(&r),
        [
            "type",
            "version",
            "versionNonce",
            "index",
            "isDeleted",
            "id",
            "fillStyle",
            "strokeWidth",
            "strokeStyle",
            "roughness",
            "opacity",
            "angle",
            "x",
            "y",
            "strokeColor",
            "backgroundColor",
            "width",
            "height",
            "seed",
            "groupIds",
            "frameId",
            "roundness",
            "boundElements",
            "updated",
            "created",
            "link",
            "locked"
        ]
    );
}

/// Which falsy values each field replaces: `||` fields replace every falsy
/// value (`0`, `""`, `false`, `null`), `??` fields only `null` and absent,
/// `opacity == null` the same.
#[test]
fn or_fields_replace_every_falsy_value_nullish_fields_only_null() {
    // (field, default, uses `||`)
    let table: &[(&str, Value, bool)] = &[
        ("version", json!(1), true),
        ("versionNonce", json!(0), false),
        ("index", Value::Null, false),
        ("isDeleted", json!(false), false),
        ("id", json!("id0"), true),
        ("fillStyle", json!("solid"), true),
        ("strokeWidth", json!(2), true),
        ("strokeStyle", json!("solid"), false),
        ("roughness", json!(1), false),
        ("opacity", json!(100), false),
        ("angle", json!(0), true),
        ("x", json!(0), false),
        ("y", json!(0), false),
        ("strokeColor", json!("#1e1e1e"), true),
        ("backgroundColor", json!("transparent"), true),
        ("width", json!(0), true),
        ("height", json!(0), true),
        ("seed", json!(1), false),
        ("groupIds", json!([]), false),
        ("frameId", Value::Null, false),
        ("roundness", Value::Null, true),
        ("boundElements", json!([]), false),
        ("updated", json!(1), false),
        ("created", Value::Null, false),
        ("link", Value::Null, true),
        ("locked", json!(false), false),
    ];
    for (field, default, uses_or) in table {
        let mut input = obj(json!({ "type": "diamond", "id": "d" }));
        if *field == "id" {
            input.remove("id");
        }
        let absent = restore_element_with_properties(&input, &[], &mut TestEnv::default())
            .expect("restores");
        assert_eq!(absent[*field], *default, "{field} absent");

        for falsy in [Value::Null, json!(0), json!(""), json!(false)] {
            let mut input = input.clone();
            input.insert((*field).to_owned(), falsy.clone());
            let r = restore_element_with_properties(&input, &[], &mut TestEnv::default())
                .expect("restores");
            let expected = if *uses_or || falsy.is_null() {
                default.clone()
            } else {
                falsy.clone()
            };
            assert_eq!(r[*field], expected, "{field} = {falsy}");
        }
    }
}

#[test]
fn present_values_are_kept_verbatim() {
    let r = restore(json!({
        "type": "ellipse", "id": "e", "version": "2", "strokeWidth": "4",
        "groupIds": "g", "locked": "yes", "opacity": 0, "roughness": 0, "seed": 0
    }));
    assert_eq!(r["version"], json!("2"));
    assert_eq!(r["strokeWidth"], json!("4"));
    assert_eq!(r["groupIds"], json!("g"));
    assert_eq!(r["locked"], json!("yes"));
    assert_eq!(r["opacity"], json!(0));
    assert_eq!(r["roughness"], json!(0));
    assert_eq!(r["seed"], json!(0));
}

/// `strokeSharpness: "round"` without a truthy `roundness` becomes
/// `{type: 1}` (legacy) for the adaptive-radius types and `{type: 2}`
/// (proportional) for every other type; then the key is deleted
/// (`restore.ts:475-485, 510-512`).
#[test]
fn stroke_sharpness_round_becomes_roundness() {
    let adaptive = ["rectangle", "embeddable", "iframe", "image"];
    let others = [
        "diamond",
        "ellipse",
        "stickynote",
        "text",
        "line",
        "arrow",
        "freedraw",
        "frame",
        "magicframe",
        "draw",
        "future-type",
    ];
    for ty in adaptive {
        let r = restore(json!({ "type": ty, "id": "x", "strokeSharpness": "round" }));
        assert_eq!(r["roundness"], json!({ "type": 1 }), "{ty}");
        assert!(!r.contains_key("strokeSharpness"));
    }
    for ty in others {
        let r = restore(json!({ "type": ty, "id": "x", "strokeSharpness": "round" }));
        assert_eq!(r["roundness"], json!({ "type": 2 }), "{ty}");
        assert!(!r.contains_key("strokeSharpness"));
    }
    for sharpness in [json!("sharp"), json!("ROUND"), json!(true), Value::Null] {
        let r = restore(json!({ "type": "rectangle", "id": "x", "strokeSharpness": sharpness }));
        assert_eq!(r["roundness"], Value::Null, "{sharpness}");
        assert!(!r.contains_key("strokeSharpness"));
    }
    // A truthy roundness wins; a falsy one does not.
    let r = restore(json!({
        "type": "rectangle", "id": "x", "roundness": { "type": 3 }, "strokeSharpness": "round"
    }));
    assert_eq!(r["roundness"], json!({ "type": 3 }));
    let r = restore(json!({
        "type": "rectangle", "id": "x", "roundness": 0, "strokeSharpness": "round"
    }));
    assert_eq!(r["roundness"], json!({ "type": 1 }));
    // The radius follows the element's own type, not the type restore
    // writes: legacy `draw` restored as `line` is proportional.
    let r = restore_with(
        json!({ "type": "draw", "id": "x", "strokeSharpness": "round" }),
        &[("type", Some(json!("line")))],
    );
    assert_eq!(r["type"], json!("line"));
    assert_eq!(r["roundness"], json!({ "type": 2 }));
}

/// `boundElementIds` becomes `boundElements: [{type: "arrow", id}]`,
/// winning over `boundElements`, and is deleted (`restore.ts:486-488`).
#[test]
fn bound_element_ids_become_bound_elements() {
    let r = restore(json!({
        "type": "rectangle", "id": "r",
        "boundElements": [{ "type": "text", "id": "t" }],
        "boundElementIds": ["a1", "a2"]
    }));
    assert_eq!(
        r["boundElements"],
        json!([{ "type": "arrow", "id": "a1" }, { "type": "arrow", "id": "a2" }])
    );
    assert_eq!(
        keys(&r["boundElements"][0].as_object().expect("object").clone()),
        ["type", "id"]
    );
    assert!(!r.contains_key("boundElementIds"));

    // An empty array is truthy: it still wins.
    let r = restore(json!({
        "type": "rectangle", "id": "r",
        "boundElements": [{ "type": "text", "id": "t" }], "boundElementIds": []
    }));
    assert_eq!(r["boundElements"], json!([]));

    // Falsy ids fall back to `boundElements ?? []`.
    let r = restore(json!({
        "type": "rectangle", "id": "r",
        "boundElements": [{ "type": "text", "id": "t" }], "boundElementIds": null
    }));
    assert_eq!(r["boundElements"], json!([{ "type": "text", "id": "t" }]));
    let r = restore(json!({ "type": "rectangle", "id": "r", "boundElements": null }));
    assert_eq!(r["boundElements"], json!([]));
}

/// A truthy value upstream calls a method on that it lacks throws, and
/// `restoreElements` drops the element (`restore.ts:977-979`).
#[test]
fn values_upstream_cannot_call_methods_on_are_errors() {
    for ids in [json!("a1"), json!({ "0": "a1" }), json!(3), json!(true)] {
        let input = obj(json!({ "type": "rectangle", "id": "r", "boundElementIds": ids }));
        let err = restore_element_with_properties(&input, &[], &mut TestEnv::default())
            .expect_err("throws");
        assert_eq!(err, RestoreError::BoundElementIdsNotArray);
        assert_eq!(
            err.to_string(),
            "element.boundElementIds.map is not a function"
        );
    }
    for link in [json!(5), json!(true), json!([]), json!({})] {
        let input = obj(json!({ "type": "rectangle", "id": "r", "link": link }));
        let err = restore_element_with_properties(&input, &[], &mut TestEnv::default())
            .expect_err("throws");
        assert_eq!(err, RestoreError::LinkNotString);
        assert_eq!(err.to_string(), "link.trim is not a function");
    }
}

/// `getNormalizedDimensions` (`packages/element/src/sizeHelpers.ts:256-283`).
#[test]
fn negative_sizes_are_flipped_and_position_moved() {
    assert_eq!(
        normalized_dimensions(10.0, 20.0, -40.0, -30.0),
        (-30.0, -10.0, 40.0, 30.0)
    );
    assert_eq!(
        normalized_dimensions(10.0, 20.0, 40.0, 30.0),
        (10.0, 20.0, 40.0, 30.0)
    );
    assert_eq!(
        normalized_dimensions(0.1, 0.0, -0.2, 0.0),
        (0.1 - 0.2, 0.0, 0.2, 0.0)
    );

    let r = restore(
        json!({ "type": "rectangle", "id": "r", "x": 10, "y": 20, "width": -40, "height": -30 }),
    );
    assert_eq!(
        (&r["x"], &r["y"], &r["width"], &r["height"]),
        (&json!(-30), &json!(-10), &json!(40), &json!(30))
    );
    // Missing x: `0 - 40`.
    let r = restore(json!({ "type": "rectangle", "id": "r", "width": -40 }));
    assert_eq!(r["x"], json!(-40));
    // Values are coerced like JS: `"-40" < 0`, `"10" - 40`.
    let r = restore(json!({ "type": "rectangle", "id": "r", "x": "10", "width": "-40" }));
    assert_eq!((&r["x"], &r["width"]), (&json!(-30), &json!(40)));
    // NaN is written as null, as JSON.stringify writes it.
    let r = restore(json!({ "type": "rectangle", "id": "r", "x": "ten", "width": -40 }));
    assert_eq!(r["x"], Value::Null);
    // `extra` is spread last, so an `extra.x` wins over the adjusted one.
    let r = restore_with(
        json!({ "type": "rectangle", "id": "r", "x": 10, "width": -40 }),
        &[("x", Some(json!(3)))],
    );
    assert_eq!((&r["x"], &r["width"]), (&json!(3), &json!(40)));
}

/// Unknown keys stay where they were; missing base keys are appended;
/// `extra` keys override in place or are appended, and an `undefined`
/// entry removes the key (`restore.ts:500-512`).
#[test]
fn key_order_follows_the_object_spread() {
    let r = restore_with(
        json!({ "future": 1, "type": "diamond", "strokeSharpness": "sharp", "id": "d", "name": "old", "gone": true }),
        &[
            ("name", Some(json!("new"))),
            ("added", Some(json!(2))),
            ("gone", None),
        ],
    );
    let k = keys(&r);
    assert_eq!(&k[..4], ["future", "type", "id", "name"]);
    assert_eq!(k.last(), Some(&"added"));
    assert!(!r.contains_key("gone"));
    assert!(!r.contains_key("strokeSharpness"));
    assert_eq!(r["name"], json!("new"));
}

#[test]
fn custom_data_is_kept_only_when_present() {
    let r = restore(json!({ "type": "rectangle", "id": "r" }));
    assert!(!r.contains_key("customData"));
    let r = restore(json!({ "type": "rectangle", "id": "r", "customData": null }));
    assert_eq!(r["customData"], Value::Null);
    let r = restore_with(
        json!({ "type": "rectangle", "id": "r", "customData": { "a": 1 } }),
        &[("customData", Some(json!({ "b": 2 })))],
    );
    assert_eq!(r["customData"], json!({ "b": 2 }));
    let r = restore_with(
        json!({ "type": "rectangle", "id": "r", "customData": { "a": 1 } }),
        &[("customData", None)],
    );
    assert!(!r.contains_key("customData"));
}

/// `normalizeLink` (`packages/common/src/url.ts:5-11`) with
/// `@braintree/sanitize-url` 6.0.2 (`dist/index.js`).
#[test]
fn links_are_normalised_and_sanitised() {
    assert_eq!(normalize_link("  https://x.test \n"), "https://x.test");
    assert_eq!(normalize_link(" \t "), "");
    assert_eq!(normalize_link("javascript:alert(1)"), "about:blank");
    assert_eq!(normalize_link("JaVaScRiPt:alert(1)"), "about:blank");
    assert_eq!(normalize_link("&#106;avascript:alert(1)"), "about:blank");
    assert_eq!(normalize_link("java&NewLine;script:x"), "about:blank");
    assert_eq!(normalize_link("javascript&colon;x"), "about:blank");
    assert_eq!(normalize_link("data:text/html,x"), "about:blank");
    assert_eq!(normalize_link("vbscript:x"), "about:blank");
    assert_eq!(normalize_link("xjavascript:x"), "xjavascript:x");
    assert_eq!(normalize_link("/path"), "/path");
    assert_eq!(normalize_link("./a:javascript:x"), "./a:javascript:x");
    assert_eq!(normalize_link("mailto:a@b.c"), "mailto:a@b.c");
    assert_eq!(
        normalize_link("https://x.test/\"q\""),
        "https://x.test/&quot;q&quot;"
    );
    assert_eq!(
        normalize_link("https://x.test/&#55357;&#56832;"),
        "https://x.test/\u{1F600}"
    );
    assert_eq!(sanitize_url(""), "about:blank");
    assert_eq!(sanitize_url("\u{1}"), "about:blank");

    let r = restore(json!({ "type": "rectangle", "id": "r", "link": "   " }));
    assert_eq!(r["link"], json!(""));
    let r = restore(json!({ "type": "rectangle", "id": "r", "link": "" }));
    assert_eq!(r["link"], Value::Null);
}

#[test]
fn test_env_mirrors_upstream_test_mode() {
    let mut env = TestEnv::default();
    assert_eq!(env.random_id(), "id0");
    assert_eq!(env.random_id(), "id1");
    assert_eq!(env.now(), 1.0);
    // A missing id draws from the environment; a present one does not.
    let mut env = TestEnv::default();
    let a = restore_element_with_properties(&obj(json!({ "type": "ellipse" })), &[], &mut env)
        .expect("restores");
    let b = restore_element_with_properties(
        &obj(json!({ "type": "ellipse", "id": "k" })),
        &[],
        &mut env,
    )
    .expect("restores");
    let c = restore_element_with_properties(
        &obj(json!({ "type": "ellipse", "id": "" })),
        &[],
        &mut env,
    )
    .expect("restores");
    assert_eq!(
        (a["id"].as_str(), b["id"].as_str(), c["id"].as_str()),
        (Some("id0"), Some("k"), Some("id1"))
    );
}

/// A legacy element from an old file restores into an object the typed
/// model reads: roundness, bound elements, flipped size and the defaults
/// land in the typed fields, unknown keys in `extra`.
#[test]
fn restored_legacy_element_reads_into_the_typed_model() {
    use excali_core::element::{
        BoundElement, BoundElementType, Element, ElementType, Roundness, RoundnessType,
    };
    let old = json!({
        "id": "old", "type": "rectangle", "x": 100, "y": 200, "width": -50, "height": 80,
        "angle": 0, "strokeColor": "#000000", "backgroundColor": "transparent",
        "fillStyle": "hachure", "strokeWidth": 1, "strokeStyle": "solid", "roughness": 1,
        "opacity": 100, "groupIds": [], "strokeSharpness": "round", "seed": 1968410350,
        "version": 141, "versionNonce": 361174001, "isDeleted": false,
        "boundElementIds": ["arrow-1"], "future": true
    });
    let element = Element::from_map(restore(old)).expect("typed model reads it");
    assert_eq!(element.element_type(), ElementType::Rectangle);
    assert_eq!(
        element.base.roundness,
        Some(Roundness::new(RoundnessType::Legacy))
    );
    assert_eq!(
        element.base.bound_elements,
        Some(vec![BoundElement {
            id: "arrow-1".into(),
            kind: BoundElementType::Arrow
        }])
    );
    assert_eq!((element.base.x, element.base.width), (50.0, 50.0));
    assert_eq!(element.base.created, None);
    assert_eq!(element.base.updated, 1.0);
    assert_eq!(element.base.index, None);
    assert_eq!(element.base.link, None);
    assert_eq!(element.extra.get("future"), Some(&json!(true)));
    assert!(!element.extra.contains_key("strokeSharpness"));
    assert!(!element.extra.contains_key("boundElementIds"));
}
